package config

import (
	"fmt"
	"os"
	"strings"
	"testing"
)

// The config file is untrusted input: it is hand-edited, generated by setup
// scripts and sometimes copied between machines. The parser is hand-written,
// so the invariant worth fuzzing is not what it returns but that a malformed
// file is always a located error and never a panic.
func FuzzParseTOML(f *testing.F) {
	// The shipped example is the canonical well-formed document.
	if data, err := os.ReadFile("../../config.example.toml"); err == nil {
		f.Add(string(data))
	}

	seeds := []string{
		"",
		"\n\n\n",
		"# just a comment\n",
		"provider = \"sqlite\"\n",
		"[turso]\nurl = \"libsql://example.turso.io\"\ntoken = \"TOKEN_GOES_HERE\"\n",
		"[d1]\naccount_id = \"00000000-0000-0000-0000-000000000000\"\n",

		// Malformed lines.
		"provider",
		"= \"sqlite\"",
		"provider =",
		"pro vider = 1",
		"provider = sqlite",
		"provider = \"a\" trailing",
		"provider = 1 # ok\nprovider = 2\n",

		// Unterminated and oddly escaped strings.
		"url = \"libsql://example.turso.io",
		"url = 'unterminated",
		"url = \"bad \\q escape\"",
		"url = \"trailing backslash \\",

		// Table headers.
		"[turso",
		"[turso.nested]\nurl = \"x\"\n",
		"[[array]]\nurl = \"x\"\n",
		"[[[[",
		"[]\nkey = 1\n",
		"[turso] junk\n",
		"[turso] # fine\n",

		// Values the subset rejects.
		"ports = [1, 2, 3]\n",
		"inline = { a = 1 }\n",
		"big = 9223372036854775808\n",
		"neg = -1\n",
		"flag = true\nother = false\n",

		// Byte-level hostility.
		"provider = \"sql\x00ite\"\n",
		"provider\x00 = 1\n",
		"\xef\xbb\xbfprovider = \"sqlite\"\n",
		"provider = \"sqlite\"\r\n[turso]\r\nurl = \"x\"\r\n",
		"provider = \"\xff\xfe invalid utf-8\"\n",
		"\xff\xfe = 1\n",
		"key = " + strings.Repeat("a", 4096) + "\n",
		strings.Repeat("# ", 5000) + "\nprovider = \"sqlite\"\n",
		strings.Repeat("[a]\nk = 1\n", 200),
	}
	for _, s := range seeds {
		f.Add(s)
	}

	f.Fuzz(func(t *testing.T, src string) {
		file, err := parseTOML(src)
		if err != nil {
			// Every rejection has to tell the user which line is wrong.
			if !strings.HasPrefix(err.Error(), "line ") {
				t.Fatalf("error does not start with a line number: %q", err)
			}
			var line int
			if _, scanErr := fmt.Sscanf(err.Error(), "line %d:", &line); scanErr != nil || line < 1 {
				t.Fatalf("error does not name a line: %q", err)
			}
			if got := strings.Count(src, "\n") + 1; line > got {
				t.Fatalf("error names line %d but the input has %d line(s): %q", line, got, err)
			}
			if file != nil {
				t.Fatalf("a rejected document returned a value as well as %q", err)
			}
			return
		}
		if file == nil {
			t.Fatal("parseTOML returned neither a document nor an error")
		}
		// An accepted document must be self-consistent: every entry has a
		// bare key, a one-level table and a known kind, and the accessors
		// must agree with it.
		for _, e := range file.entries {
			if err := checkBareKey(e.key, e.value.line); err != nil {
				t.Fatalf("accepted an invalid key: %v", err)
			}
			if e.table != "" {
				if err := checkBareKey(e.table, e.value.line); err != nil {
					t.Fatalf("accepted an invalid table name: %v", err)
				}
			}
			switch e.value.kind {
			case kindString, kindInt, kindBool:
			default:
				t.Fatalf("entry %s.%s has an unknown kind %d", e.table, e.key, e.value.kind)
			}
			if v, ok := file.lookup(e.table, e.key); !ok || v.kind != e.value.kind {
				t.Fatalf("lookup disagrees with the entry list for %s.%s", e.table, e.key)
			}
			if e.value.kind == kindString {
				if _, ok := file.string(e.table, e.key); !ok {
					t.Fatalf("string accessor lost %s.%s", e.table, e.key)
				}
			}
		}
	})
}
